__NUXT_JSONP__("/sp/firstday-at-mli", (function(a){return {data:[{details:{slug:"sp",pageTitle:"Primer día en MLI | Mentor Language Institute",pageDescription:a,title:"Primer día en MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffirst-day-at-mli\u002Fmli-signup.jpg",categories:[{title:"¡Bienvenido a Mentor Language Institute!",description:[a,"Esta orientación le proporcionará información importante y necesaria para aumentar su comprensión de nuestros programas, las normas de inmigración y las reglas de la escuela, y le ayudará a cumplir todos sus objetivos académicos. \u003Cbr \u002F\u003ECuando llegue a la escuela, será recibido por nuestro personal de la Oficina de Admisiones, nuestros profesores, la recepción y el personal administrativo."],dates:["＜Fecha de inicio de cada trimestre＞","- May 22nd, 2023 \u003Cbr\u002F\u003E - June 20th, 2023 \u003Cbr\u002F\u003E - July 17th, 2023 \u003Cbr\u002F\u003E - August 14th, 2023 \u003Cbr\u002F\u003E - September 11th, 2023 \u003Cbr\u002F\u003E - October 10th, 2023 \u003Cbr\u002F\u003E - November 6th, 2023 \u003Cbr\u002F\u003E - December 4th, 2023 \u003Cbr\u002F\u003E - January 8th, 2024 \u003Cbr\u002F\u003E - February 5th, 2024 \u003Cbr\u002F\u003E - March 4th, 2024","La orientación comienza a la 1 pm."],groups:[{title:"Orientación y examen de nivel",listType:"table",lists:[{key:"1:00pm – 1:30pm",value:"Documentación de inscripción"},{key:"1:30pm – 2:00pm",value:"Orientación Académica"},{key:"2:00pm – 3:00pm",value:"Prueba de nivel"},{key:"3:15pm – 3:35pm",value:"Políticas del Instituto, Reglas de Inmigración"},{key:"3:35pm – 3:50pm",value:"Servicio de transferencia de la universidad"},{key:"3:50pm – 4:00pm",value:"Actividades y alojamiento"},{key:"4:00pm – 4:10pm",value:"Examen oral y elección de nivel"},{key:"4:10pm – 4:20pm",value:"Compra de libros de texto"}]},{title:"Qué traer en su primer día",lists:["Pasaporte (si es titular de una visa de estudiante)","I-20 (si es titular de una visa de estudiante)","Lápiz y papel","Dinero para la compra de los libros de texto y el pago de la matrícula"]}]},{title:"Detalles",groups:[{title:"Horario de la orientación",description:["Primero, completará la documentación necesaria para la inscripción.\u003Cbr \u002F\u003EA continuación, el Director Académico o el Coordinador de Programa dará una presentación sobre nuestros diferentes programas, reglas de clase, y cómo tener éxito en sus estudios para pasar de un nivel a otro, y de un programa a otro."]},{title:"Examen de nivel y entrevista",description:["Después de la orientación, tomará el \"Examen de nivel de Inglés\", que consiste en aproximadamente 80 preguntas. El exámen contiene preguntas de comprensión y escritura que cubren gramática, vocabulario y comprensión lectora. Es un examen de 60 minutos que le ayudará a determinar su nivel de inglés. \u003Cbr \u002F\u003EDespués del examen, tendras una prueba de conversación rápida (más como una entrevista) con uno de nuestros instructores (ya sea la PC, el AD o un profesor de MLI).\u003Cbr \u002F\u003EEsta prueba es para ayudarlo a finalizar su elección del nivel y\u002Fo programa más apropiado según sus habilidades y objetivos."]},{title:"Compra de los libros de texto",description:["Después del examen de nivel y la entrevista, deberá comprar los libros de texto al personal de la recepción.\u003Cbr \u002F\u003E El personal de recepción está disponible para responder cualquier pregunta o inquietud adicional que puedan tener los estudiantes."]}]}],dir:"\u002Ffirstday-at-mli",path:"\u002Ffirstday-at-mli\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:29.270Z",updatedAt:"2025-05-26T12:06:27.757Z"}}],fetch:{},mutations:void 0}}("En MLI, tenemos una sesión de orientación para nuevos estudiantes al comienzo de cada semestre (cada 4 semanas).")));